parts.text:
[
  {
    "statement": "Supplementary feeding has demonstrated effectiveness in increasing farmland bird populations.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Wild bird seed mixtures have demonstrated effectiveness in increasing farmland bird populations.",
    "citations": [
      "594",
      "3930",
      "187"
    ]
  },
  {
    "statement": "The reviewed studies do not provide direct cost-effectiveness comparisons between supplementary feeding and wild bird seed mixtures.",
    "citations": []
  },
  {
    "statement": "Supplementary feeding showed positive effects in 9 out of 18 studies.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Positive effects of supplementary feeding included increased bird abundance, breeding population size, density, and body mass.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Positive effects of supplementary feeding included increased hatching rates, nestling growth rates, and overwinter survival.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Five studies found no clear effects of supplementary feeding on various bird population parameters.",
    "citations": [
      "648"
    ]
  },
  {
    "statement": "Wild bird seed mixtures showed consistently positive results, with 21 out of 30 studies finding positive effects on birds.",
    "citations": [
      "594",
      "3930",
      "187"
    ]
  },
  {
    "statement": "The positive effects of wild bird seed mixtures included higher bird abundance, density, species diversity, and species richness compared to other farmland habitats.",
    "citations": [
      "594",
      "3930",
      "187"
    ]
  },
  {
    "statement": "Multiple studies found that birds showed a preference for wild bird cover.",
    "citations": [
      "594",
      "3930",
      "187"
    ]
  },
  {
    "statement": "Birds used wild bird cover significantly more than other habitats.",
    "citations": [
      "594",
      "3930",
      "187"
    ]
  },
  {
    "statement": "A systematic review and multiple controlled trials consistently supported wild bird seed mixtures as beneficial for farmland birds.",
    "citations": []
  },
  {
    "statement": "Some studies specifically noted increased grey partridge populations when conservation measures including cover crops were implemented.",
    "citations": []
  },
  {
    "statement": "None of the reviewed studies provided specific cost data comparing supplementary feeding and wild bird seed mixtures.",
    "citations": []
  },
  {
    "statement": "None of the reviewed studies provided an economic analysis directly comparing supplementary feeding and wild bird seed mixtures.",
    "citations": []
  }
]

[
  {
    "statement": "The evidence for beetle bank effectiveness in conserving native predator insects shows mixed results.",
    "citations": [
      "729",
      "651",
      "217",
      "2393",
      "3927"
    ]
  },
  {
    "statement": "Six studies from Canada, the UK and USA found that predators increased in crops adjacent to beetle banks.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "The effects of beetle banks on predator populations varied with time.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "One study found beetle banks had no effect on predator populations.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Two studies found small or slow movements of predators from beetle banks to crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Four studies found more invertebrate predators on beetle banks than in surrounding crops.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "The effects of beetle banks on invertebrate predator numbers varied with time.",
    "citations": [
      "729"
    ]
  },
  {
    "statement": "Five reports from two replicated studies found that beetle banks had positive effects on invertebrate densities and numbers.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Five reports from two replicated studies found a higher ground beetle density in beetle banks during the spring and summer.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Six reports from three studies found that invertebrate numbers varied between grass species sown on beetle banks.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Five studies found lower or no difference in invertebrate densities on beetle banks compared to other habitats.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Economic benefits from beetle banks were demonstrated if the beetle banks prevented pests from reaching spray thresholds.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Economic benefits from beetle banks were demonstrated if the beetle banks prevented pests from causing a 5% yield loss.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Design considerations for beetle banks were important.",
    "citations": [
      "651"
    ]
  },
  {
    "statement": "Certain grass species used in beetle banks supported higher numbers of predatory invertebrates than other grass species.",
    "citations": [
      "651"
    ]
  }
]

[
  {
    "statement": "There is limited evidence from a randomised, replicated, and controlled study from the UK regarding fence marking.",
    "citations": [
      "238"
    ]
  },
  {
    "statement": "The UK study found that fewer birds collided with deer fences marked with orange netting than with unmarked sections.",
    "citations": [
      "238"
    ]
  },
  {
    "statement": "For another action about marking fencing to avoid bird mortality, there is no evidence available to assess its effectiveness.",
    "citations": [
      "706"
    ]
  },
  {
    "statement": "There is currently no evidence available to assess the effectiveness of avoiding lead shot use for protecting farmland wildlife.",
    "citations": [
      "100"
    ]
  },
  {
    "statement": "No studies have been found that directly and quantitatively tested the action of avoiding lead shot use.",
    "citations": [
      "100"
    ]
  },
  {
    "statement": "Marking fencing currently has some supporting evidence of effectiveness from at least one controlled study.",
    "citations": [
      "238"
    ]
  },
  {
    "statement": "Avoiding the use of lead shot lacks quantitative evidence specifically for farmland bird protection.",
    "citations": [
      "100"
    ]
  }
]
